CREATE TABLE runtime_job_v1 (job_id TEXT PRIMARY KEY CHECK(length(CAST(job_id AS BLOB)) BETWEEN 1 AND 128),schema_version INTEGER NOT NULL CHECK(schema_version=1),workspace_id TEXT NOT NULL REFERENCES workspace(workspace_id),work_item_id TEXT,session_id TEXT,root_session_id TEXT,delegation_id TEXT,agent_role TEXT CHECK(agent_role IS NULL OR agent_role IN('root','series','task','reviewer')),context_generation INTEGER CHECK(context_generation IS NULL OR context_generation>=0),submission_boot_id TEXT CHECK(submission_boot_id IS NULL OR length(CAST(submission_boot_id AS BLOB)) BETWEEN 1 AND 128),attestation_ref TEXT CHECK(attestation_ref IS NULL OR length(CAST(attestation_ref AS BLOB)) BETWEEN 1 AND 1024),attestation_digest TEXT CHECK(attestation_digest IS NULL OR (length(attestation_digest)=64 AND attestation_digest NOT GLOB '*[^0-9a-f]*')),grant_schema_version INTEGER,grant_json TEXT,grant_digest TEXT CHECK(grant_digest IS NULL OR (length(grant_digest)=64 AND grant_digest NOT GLOB '*[^0-9a-f]*')),grant_byte_len INTEGER CHECK(grant_byte_len IS NULL OR grant_byte_len BETWEEN 2 AND 65536),identity_digest TEXT CHECK(identity_digest IS NULL OR (length(identity_digest)=64 AND identity_digest NOT GLOB '*[^0-9a-f]*')),workspace_mode TEXT NOT NULL CHECK(workspace_mode IN('legacy','shadow','rust_canary','rust_sole_writer')),inventory_generation INTEGER NOT NULL CHECK(inventory_generation>=0),entrypoint TEXT NOT NULL CHECK(length(CAST(entrypoint AS BLOB)) BETWEEN 1 AND 128),arguments_schema_version INTEGER NOT NULL CHECK(arguments_schema_version=1),arguments_json TEXT NOT NULL,arguments_digest TEXT NOT NULL CHECK(length(arguments_digest)=64 AND arguments_digest NOT GLOB '*[^0-9a-f]*'),arguments_byte_len INTEGER NOT NULL CHECK(arguments_byte_len BETWEEN 2 AND 65536),submission_scope_digest TEXT NOT NULL CHECK(length(submission_scope_digest)=64 AND submission_scope_digest NOT GLOB '*[^0-9a-f]*'),submission_idempotency_key TEXT NOT NULL CHECK(length(CAST(submission_idempotency_key AS BLOB)) BETWEEN 1 AND 256),submission_idempotency_key_digest TEXT NOT NULL CHECK(length(submission_idempotency_key_digest)=64 AND submission_idempotency_key_digest NOT GLOB '*[^0-9a-f]*'),request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),source_revision INTEGER CHECK(source_revision IS NULL OR source_revision>=0),input_fingerprint TEXT CHECK(input_fingerprint IS NULL OR (length(input_fingerprint)=64 AND input_fingerprint NOT GLOB '*[^0-9a-f]*')),deadline_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('queued','running','pass','fail','error','timeout','cancelled','stale')),row_version INTEGER NOT NULL CHECK(row_version>=0),result_schema_version INTEGER CHECK(result_schema_version IS NULL OR result_schema_version=1),result_json TEXT,result_digest TEXT CHECK(result_digest IS NULL OR (length(result_digest)=64 AND result_digest NOT GLOB '*[^0-9a-f]*')),result_byte_len INTEGER CHECK(result_byte_len IS NULL OR result_byte_len BETWEEN 2 AND 65536),error_code TEXT CHECK(error_code IS NULL OR length(CAST(error_code AS BLOB)) BETWEEN 1 AND 128),mutation_id TEXT CHECK(mutation_id IS NULL OR length(CAST(mutation_id AS BLOB)) BETWEEN 1 AND 128),receipt_locator TEXT CHECK(receipt_locator IS NULL OR length(CAST(receipt_locator AS BLOB)) BETWEEN 1 AND 1024),project_receipt_digest TEXT CHECK(project_receipt_digest IS NULL OR (length(project_receipt_digest)=64 AND project_receipt_digest NOT GLOB '*[^0-9a-f]*')),submitted_event_seq INTEGER NOT NULL REFERENCES runtime_event(event_seq),last_event_seq INTEGER NOT NULL REFERENCES runtime_event(event_seq),created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT,updated_at TEXT NOT NULL,UNIQUE(submission_scope_digest,submission_idempotency_key),CHECK(arguments_byte_len=length(CAST(arguments_json AS BLOB)) AND json_valid(arguments_json) AND json_type(arguments_json)='object'),CHECK((source_revision IS NULL)=(input_fingerprint IS NULL)),CHECK((session_id IS NULL AND root_session_id IS NULL AND delegation_id IS NULL AND agent_role IS NULL AND context_generation IS NULL AND submission_boot_id IS NULL AND attestation_ref IS NULL AND attestation_digest IS NULL AND grant_schema_version IS NULL AND grant_json IS NULL AND grant_digest IS NULL AND grant_byte_len IS NULL AND identity_digest IS NULL) OR (session_id IS NOT NULL AND root_session_id IS NOT NULL AND agent_role IS NOT NULL AND context_generation IS NOT NULL AND submission_boot_id IS NOT NULL AND attestation_ref IS NOT NULL AND attestation_digest IS NOT NULL AND grant_schema_version IS NOT NULL AND grant_schema_version=1 AND grant_json IS NOT NULL AND grant_digest IS NOT NULL AND grant_byte_len IS NOT NULL AND grant_byte_len=length(CAST(grant_json AS BLOB)) AND json_valid(grant_json) AND json_type(grant_json)='object' AND identity_digest IS NOT NULL AND ((session_id=root_session_id AND delegation_id IS NULL AND agent_role='root') OR (session_id<>root_session_id AND delegation_id IS NOT NULL AND agent_role IN('series','task','reviewer'))))),CHECK(entrypoint NOT IN('toolset.required','toolset.receipt.record') OR (work_item_id IS NOT NULL AND session_id IS NOT NULL AND source_revision IS NOT NULL AND input_fingerprint IS NOT NULL)),CHECK((result_json IS NULL AND result_schema_version IS NULL AND result_digest IS NULL AND result_byte_len IS NULL) OR (result_json IS NOT NULL AND result_schema_version IS NOT NULL AND result_schema_version=1 AND result_digest IS NOT NULL AND result_byte_len IS NOT NULL AND result_byte_len=length(CAST(result_json AS BLOB)) AND json_valid(result_json) AND json_type(result_json)='object')),CHECK((status='queued' AND started_at IS NULL AND finished_at IS NULL AND result_json IS NULL AND error_code IS NULL) OR (status='running' AND started_at IS NOT NULL AND finished_at IS NULL AND result_json IS NULL AND error_code IS NULL) OR (status IN('pass','fail','stale') AND started_at IS NOT NULL AND finished_at IS NOT NULL AND result_json IS NOT NULL AND error_code IS NULL) OR (status IN('error','timeout') AND started_at IS NOT NULL AND finished_at IS NOT NULL AND result_json IS NULL AND error_code IS NOT NULL) OR (status='cancelled' AND finished_at IS NOT NULL AND result_json IS NULL AND error_code IS NOT NULL)),CHECK((mutation_id IS NULL AND receipt_locator IS NULL AND project_receipt_digest IS NULL) OR (mutation_id IS NOT NULL AND receipt_locator IS NOT NULL AND project_receipt_digest IS NOT NULL)),CHECK(entrypoint<>'toolset.receipt.record' OR status<>'pass' OR (mutation_id IS NOT NULL AND receipt_locator IS NOT NULL AND project_receipt_digest IS NOT NULL)),CHECK(last_event_seq>=submitted_event_seq),FOREIGN KEY(workspace_id,session_id) REFERENCES agent_session(workspace_id,session_id),FOREIGN KEY(workspace_id,root_session_id) REFERENCES agent_session(workspace_id,session_id),FOREIGN KEY(workspace_id,delegation_id) REFERENCES delegation(workspace_id,delegation_id));CREATE INDEX runtime_job_v1_recovery ON runtime_job_v1(status,submitted_event_seq,job_id) WHERE status IN('queued','running'); CREATE INDEX runtime_job_v1_deadline ON runtime_job_v1(status,deadline_at,job_id) WHERE status IN('queued','running'); CREATE INDEX runtime_job_v1_work_item_status ON runtime_job_v1(workspace_id,work_item_id,status,job_id); CREATE INDEX runtime_job_v1_event_cursor ON runtime_job_v1(workspace_id,last_event_seq); PRAGMA user_version=10;
